select count(*) as c from hits
select count(*) as c from hits where AdvEngineID <> 0
select sum(AdvEngineID) as s, count(*) as c, avg(ResolutionWidth) as w from hits
select avg(UserID) as a from hits
select nunique(UserID) as u from hits
select nunique(SearchPhrase) as u from hits
select min(EventDate) as mn, max(EventDate) as mx from hits
select AdvEngineID, count(*) as c from hits where AdvEngineID <> 0 group by AdvEngineID order by c desc
select RegionID, nunique(UserID) as u from hits group by RegionID order by u desc limit 10
select RegionID, sum(AdvEngineID) as s, count(*) as c, avg(ResolutionWidth) as w, nunique(UserID) as u from hits group by RegionID order by c desc limit 10
select MobilePhoneModel, nunique(UserID) as u from hits where MobilePhoneModel <> '' group by MobilePhoneModel order by u desc limit 10
select MobilePhone, MobilePhoneModel, nunique(UserID) as u from hits where MobilePhoneModel <> '' group by MobilePhone, MobilePhoneModel order by u desc limit 10
select SearchPhrase, count(*) as c from hits where SearchPhrase <> '' group by SearchPhrase order by c desc limit 10
select SearchPhrase, nunique(UserID) as u from hits where SearchPhrase <> '' group by SearchPhrase order by u desc limit 10
select SearchEngineID, SearchPhrase, count(*) as c from hits where SearchPhrase <> '' group by SearchEngineID, SearchPhrase order by c desc limit 10
select UserID, count(*) as c from hits group by UserID order by c desc limit 10
select UserID, SearchPhrase, count(*) as c from hits group by UserID, SearchPhrase order by c desc limit 10
select UserID, SearchPhrase, count(*) as c from hits group by UserID, SearchPhrase limit 10
select UserID, m, SearchPhrase, count(*) as c from hits group by UserID, minuteOfHour(EventTime) as m, SearchPhrase order by c desc limit 10
select UserID from hits where UserID = 435090932899640449
select count(*) as c from hits where URL like '%google%'
select SearchPhrase, min(URL) as mu, count(*) as c from hits where URL like '%google%' and SearchPhrase <> '' group by SearchPhrase order by c desc limit 10
select SearchPhrase, min(URL) as mu, min(Title) as mt, count(*) as c, nunique(UserID) as u from hits where Title like '%Google%' and not (URL like '%.google.%') and SearchPhrase <> '' group by SearchPhrase order by c desc limit 10
select * from hits where URL like '%google%' order by EventTime limit 10
select SearchPhrase from hits where SearchPhrase <> '' order by EventTime limit 10
select SearchPhrase from hits where SearchPhrase <> '' order by SearchPhrase limit 10
select SearchPhrase from hits where SearchPhrase <> '' order by EventTime, SearchPhrase limit 10
select CounterID, avg(strlen(URL)) as l, count(*) as c from hits where URL <> '' group by CounterID having count(*) > 100000 order by l desc limit 25
select k, avg(strlen(Referer)) as l, count(*) as c, min(Referer) as mr from hits where Referer <> '' group by regexReplace(Referer, '^https?://(www[.])?([^/]+)/.*$', '$2') as k having count(*) > 100000 order by l desc limit 25
