select SearchEngineID, ClientIP, count(*) as c, sum(IsRefresh) as r, avg(ResolutionWidth) as w from hits where SearchPhrase <> '' group by SearchEngineID, ClientIP order by c desc limit 10
select WatchID, ClientIP, count(*) as c, sum(IsRefresh) as r, avg(ResolutionWidth) as w from hits where SearchPhrase <> '' group by WatchID, ClientIP order by c desc limit 10
select WatchID, ClientIP, count(*) as c, sum(IsRefresh) as r, avg(ResolutionWidth) as w from hits group by WatchID, ClientIP order by c desc limit 10
select URL, count(*) as c from hits group by URL order by c desc limit 10
select 1 as one, URL, count(*) as c from hits group by URL order by c desc limit 10
select ClientIP, c1, c2, c3, count(*) as c from hits group by ClientIP, ClientIP - 1 as c1, ClientIP - 2 as c2, ClientIP - 3 as c3 order by c desc limit 10
select URL, count(*) as PageViews from hits where CounterID = 62 and EventDate >= 2013.07.01 and EventDate <= 2013.07.31 and DontCountHits = 0 and IsRefresh = 0 and URL <> '' group by URL order by PageViews desc limit 10
select Title, count(*) as PageViews from hits where CounterID = 62 and EventDate >= 2013.07.01 and EventDate <= 2013.07.31 and DontCountHits = 0 and IsRefresh = 0 and Title <> '' group by Title order by PageViews desc limit 10
select * from (select URL, count(*) as PageViews from hits where CounterID = 62 and EventDate >= 2013.07.01 and EventDate <= 2013.07.31 and IsRefresh = 0 and IsLink <> 0 and IsDownload = 0 group by URL) order by PageViews desc limit 1000, 10
select * from (select TraficSourceID, SearchEngineID, AdvEngineID, Src, Dst, count(*) as PageViews from hits where CounterID = 62 and EventDate >= 2013.07.01 and EventDate <= 2013.07.31 and IsRefresh = 0 group by TraficSourceID, SearchEngineID, AdvEngineID, case when (SearchEngineID = 0 and AdvEngineID = 0) then Referer else '' end as Src, URL as Dst) order by PageViews desc limit 1000, 10
select * from (select URLHash, EventDate, count(*) as PageViews from hits where CounterID = 62 and EventDate >= 2013.07.01 and EventDate <= 2013.07.31 and IsRefresh = 0 and TraficSourceID in (-1, 6) and RefererHash = 3594120000172545465 group by URLHash, EventDate) order by PageViews desc limit 100, 10
select * from (select WindowClientWidth, WindowClientHeight, count(*) as PageViews from hits where CounterID = 62 and EventDate >= 2013.07.01 and EventDate <= 2013.07.31 and IsRefresh = 0 and DontCountHits = 0 and URLHash = 2868770270353813622 group by WindowClientWidth, WindowClientHeight) order by PageViews desc limit 10000, 10
select * from (select M, count(*) as PageViews from hits where CounterID = 62 and EventDate >= 2013.07.14 and EventDate <= 2013.07.15 and IsRefresh = 0 and DontCountHits = 0 group by bar(EventTime, 60) as M) order by M limit 1000, 10
